as ref,(select to_jsonb(t) from public.editions t where t.id=987235004)='{"id":987235004,"title":"Robbie de Hand","isbn_10":null,"isbn_13":"9789022534847","work_id":987135004,"cover_id":null,"language":"dut","publisher":"Uitgeverij M","publish_date":null,"open_library_edition_id":"OL32843390M"}'::jsonb as exact union all select 'catalog_work_descriptions:26' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987135004 and t.language='nl')='{"text":"De jonge dief Robbie kent de schaduwkanten van Krondor goed, maar hulp aan prins Arutha brengt hem tegenover gevaarlijke tegenstanders te staan. Hij moet de stad verlaten en zoekt elders een nieuw bestaan. Zijn behendigheid en talent om andermans bezit te vinden lijken daarbij van pas te komen. De plaats die als toevlucht dient blijkt echter eigen geheimen en misdadigers te hebben. Robbie raakt opnieuw in moeilijkheden die verder gaan dan gewone diefstal.","work_id":987135004,"evidence":[{"note":"Exact Robbie de Hand9789022534847; Legends of Riftwar3, RaymondFeist metSteveStirling. Auteurssynopsis bevestigt Krondor/Arutha en vlucht naarLandsEnd. Beide auteurs onderscheiden, geen omnibus ofRobbie-storiesbundel.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p252124731"],"reference":"new-work-dossier-readings-036.json#78","checked_at":"2026-11-03T07:32:53.960Z"},{"type":"original_substantive_source_review","review":"content-review-007.json","sources":["https://www.crydee.com/raymond-feist/book-synopsis/jimmy-the-hand","https://data.bibliotheken.nl/id/nbt/p252124731","https://openlibrary.org/works/OL554703W"]},{"type":"explicit_contributor_roles","credits":[{"name":"S. M. Stirling","role":"coauthor","source":"https://www.crydee.com/raymond-feist/publication-information/netherlands/legends-of-the-riftwar"}],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Bounded official bu