987335003,"work_type":null,"source_type":"open_library","open_library_id":"OL7918929W","first_publish_year":1984,"native_identity_key":"nlscale:20261102:ol:OL7918929W"}'::jsonb as exact union all select 'editions:29' as ref,(select to_jsonb(t) from public.editions t where t.id=987235005)='{"id":987235005,"title":"Op Zoek naar Schrödingers Kat","isbn_10":null,"isbn_13":"9789025466015","work_id":987135005,"cover_id":null,"language":"dut","publisher":"Contact","publish_date":null,"open_library_edition_id":"OL25697332M"}'::jsonb as exact union all select 'catalog_work_descriptions:30' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987135005 and t.language='nl')='{"text":"John Gribbin introduceert de ideeën waarmee de quantumfysica het beeld van de natuur veranderde. Hij volgt de wetenschappers die de theorie ontwikkelden en bespreekt verschijnselen rond atomen, straling en de betekenis van metingen. De vragen gaan niet alleen over berekeningen, maar ook over wat de theorie over de werkelijkheid zegt. Het boek is bedoeld als toegankelijke verkenning voor lezers zonder specialistische voorkennis en verbindt de geschiedenis van ontdekkingen met hun moeilijke interpretatie.","work_id":987135005,"evidence":[{"note":"ExactDutch9789025466015 vertaalt InSearchOfSchrodingersCat1984. John/JonathanRGribbin zijn gebonden via bronauthoriteit en exacte titel; geen fictieroman of automatische smaaktesttoelating.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p851796753"],"reference":"new-work-dossier-readings-036.json#79","checked_at":"2026-11-03T07:32:53.960Z"},{"type":"original_substantive_source_review","review":"content-review-007.json","sources":["https://data.bibliotheken.nl/id/nbt/p851796753","https://openlibrary.org/works/OL7918929W"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge.